    forbidden = {"private_key", "secret", "signature", "payload", "content"}
    text = json.dumps(package)

    def walk(value):
        if isinstance(value, dict):
            for key, member in value.items():
                assert key not in forbidden
                yield from walk(member)
        elif isinstance(value, list):
            for member in value:
                yield from walk(member)

    list(walk(package["resources"]))
    # Only signature *digests* and public keys ever appear.
    assert "signature_digest_hex" in text
    assert "public_key" in text

